// The acceptance report, generated by `fwos report` and never hand-edited. It holds every
// AC with its verdict and evidence, every check that was off and why, every [ASSUMED] item, skip
// and override, and the gaps and manual checks waiting for a named sign-off. Deterministic: the
// same evidence gives the same file, so an approval of it stays valid until the evidence changes.

import { posix } from 'node:path';
import { type CheckResult, type Project, hashPath } from '../../kernel/index.ts';
import { changeDrift } from '../build/index.ts';
import { loadDesignSystem } from '../design-system/index.ts';
import { acDelta, specPath } from '../spec/index.ts';
import { type Change, changeApprovalState, isAdoptionRecord, listChanges, readBaseline } from '../state/index.ts';
import { browserResults, parseRegressionScope, parseTestPlan, readTestRuns, regressionResults, tally, testPlanPath, traceAcs } from '../tests/index.ts';
import { VERDICT_LABEL, reportPath, traceChange, traceMarkdown } from './trace.ts';

export { reportPath };

export const REPORT_HEADER = '<!-- generated by `fwos report`; do not edit. It is rebuilt from the evidence. -->';

export interface Report {
  markdown: string;
  done: boolean;
  blockers: string[];
}

const esc = (s: string) => s.replace(/\|/g, '\\|').replace(/\n/g, ' ');

function signoffs(changes: Change[]): Map<string, { by: string; at: string; note?: string }> {
  const out = new Map<string, { by: string; at: string; note?: string }>();
  for (const c of changes) for (const s of c.signoffs ?? []) out.set(s.item, s);
  return out;
}

function assumptions(project: Project): string[] {
  const out: string[] = [];
  for (const f of project.files([`${project.paths.docs}/*.md`])) {
    const text = project.read(f) ?? '';
    for (const line of text.split('\n')) {
      if (!line.includes('[ASSUMED]')) continue;
      const clean = line.trim().startsWith('|')
        ? line
            .split('|')
            .map((c) => c.trim())
            .filter(Boolean)
            .join(' · ')
        : line.replace(/^\s*[-*]\s*/, '').trim();
      out.push(`${posix.basename(f)}: ${clean.length > 220 ? `${clean.slice(0, 217)}...` : clean}`);
    }
  }
  try {
    for (const a of loadDesignSystem(project)?.config.assumed ?? []) out.push(`design system: ${a}`);
  } catch {
    // a broken design system is reported by its own check
  }
  return out;
}

/**
 * What the change came from, as it stands now: each linked issue or doc, and whether a linked file
 * changed since it was linked. Context the change builds on, never an approval.
 */
function linkedContext(project: Project, change: Change | undefined): string[] {
  if (!change?.links?.length) return [];
  const lines = change.links.map((l) => linkLine(project, l));
  return ['## Request and linked context', '', `${change.id}: ${esc(change.title)}. Linked context, as it stands now. It is what the change builds on, not an approval.`, '', ...lines, ''];
}

const linkLine = (project: Project, l: NonNullable<Change['links']>[number]) =>
  `- ${l.ref}${l.sha ? (hashPath(project.abs(l.ref)) === l.sha ? ' (unchanged since it was linked)' : ' (changed since it was linked)') : ''}`;

/**
 * What people approved in an adopted app's change, as they gave it, and the criteria that makes
 * its own. Its acceptance is approved on the report itself, so the report can't say it.
 */
function approvedInChange(project: Project, change: Change): string[] {
  // A team that keeps its own acceptance signs off in its own tool, and links the sign-off.
  const signoff = (change.links ?? []).filter((l) => l.stage === 'acceptance').map((l) => l.ref);
  const acceptance = project.kept.includes('acceptance')
    ? `Its acceptance is your team's, signed off ${signoff.length > 0 ? `in ${signoff.join(', ')}` : 'where the change will link it'}.`
    : 'Its acceptance is approved on this report itself.';
  const out = ['## Approved in this change', '', `What people approved for ${change.id}, as they gave it. ${acceptance}`, ''];
  if (change.route === 'code-only') return [...out, '- No spec: a code-only change has no spec delta to approve.', ''];
  const s = changeApprovalState(project, change, 'spec');
  const r = s.record;
  const where = !r ? '' : r.ref ? ` in ${r.ref}` : r.via === 'autopilot' ? ' by autopilot (scripted answers), not by a person' : ` in ${r.via === 'pr' ? 'a pull request' : r.via}`;
  const who = r ? `approved by ${r.by} on ${r.at.slice(0, 10)}${where}` : '';
  const line = s.status === 'approved' ? who : s.status === 'stale' ? `${who}, but ${(s.changed ?? []).join(', ')} changed since` : `not approved yet (${s.status})`;
  const spec = project.read(specPath(project));
  const d = spec === null ? null : acDelta(change, spec);
  const parts = d ? [d.added.length > 0 && `It adds ${d.added.join(', ')}.`, d.changed.length > 0 && `It changes ${d.changed.join(', ')}.`].filter(Boolean) : [];
  const delta = !d ? '' : parts.length > 0 ? ` ${parts.join(' ')}` : ' It adds or changes no criterion.';
  return [...out, `- Spec and test plan: ${line}.${delta}`, ''];
}

/**
 * What an adopted app's change builds on, none of it approved in it: the request and the links it
 * came with, the code it was mapped onto, the criteria earlier changes approved, the team's own
 * tests it runs as regression, and the debt the baseline holds.
 */
function importedContext(project: Project, change: Change, changes: Change[]): string[] {
  const out = ['## Imported context', '', 'What the change builds on. None of it was approved in this change.', '', `- Request: "${esc(change.title)}"`, ...(change.links ?? []).map((l) => linkLine(project, l))];
  if (change.map) out.push(`- Grounded in: ${change.map.targets.map((t) => (t.target === t.file ? t.file : `${t.target} (${t.file})`)).join(', ')}`);
  const spec = project.read(specPath(project));
  const carried = spec === null ? [] : (acDelta(change, spec)?.carried ?? []);
  if (carried.length > 0) {
    // Each criterion came from the change whose start didn't have it yet, before the next one's did.
    const earlier = changes.filter((c) => c.id < change.id && c.base && !isAdoptionRecord(project, c));
    const from = (ac: string) => {
      let adder: string | null = null;
      for (const c of earlier) {
        if (!(ac in c.base!.acs)) adder = c.id;
        else if (adder) break;
      }
      return adder ?? 'before fwos recorded them';
    };
    const groups = new Map<string, string[]>();
    for (const ac of carried) groups.set(from(ac), [...(groups.get(from(ac)) ?? []), ac]);
    out.push(`- Criteria carried from earlier changes: ${[...groups].map(([c, acs]) => `${acs.join(', ')} (from ${c})`).join('; ')}`);
  }
  const plan = project.read(testPlanPath(project));
  const scope = plan === null ? null : parseRegressionScope(plan);
  if (scope?.entries.length) out.push(`- Existing tests run as regression: ${scope.entries.map((e) => e.path).join(', ')}`);
  else if (scope?.none) out.push('- Existing tests run as regression: none, as the test plan says');
  out.push('- Pre-existing debt: the baseline, below', '');
  return out;
}

/**
 * The team's own commands as `fwos tests run` last ran them on this code, and the regression scope
 * as it last ran. A run of other code is named, never counted.
 */
function runsAndRegression(project: Project): string[] {
  const out: string[] = [];
  const runs = readTestRuns(project);
  const fresh = runs.filter((r) => r.fresh);
  const stale = runs.filter((r) => !r.fresh).map((r) => r.display);
  if (runs.length > 0) out.push('## Test runs', '');
  if (fresh.length > 0) {
    out.push('Your own commands, as `fwos tests run` last ran them on this code:', '', '| Command | Runner | Result | Results |', '|---|---|---|---|');
    for (const r of fresh) {
      const runner = `${r.runner ?? 'unknown'}${r.browser ? ', in a browser' : ''}${r.mapped ? '' : ', not mapped'}`;
      const res = r.mapped ? `${r.exit !== 0 && r.cases.failed === 0 ? `exit ${r.exit}, ` : ''}${tally(r.cases)}` : `exit ${r.exit}`;
      out.push(`| ${esc(r.display)} | ${esc(runner)} | ${res} | ${esc(r.mapped ? r.results.join(', ') : (r.reason ?? ''))} |`);
    }
    out.push('');
  }
  if (stale.length > 0) {
    const names = stale.length < 2 ? stale.join('') : `${stale.slice(0, -1).join(', ')} and ${stale.at(-1)}`;
    out.push(`Not counted, since the code changed after ${stale.length === 1 ? 'it' : 'they'} ran: ${esc(names)}. Run ${stale.length === 1 ? 'it' : 'them'} again with \`fwos tests run\`.`, '');
  }
  const plan = project.read(testPlanPath(project));
  const entries = plan === null ? [] : parseRegressionScope(plan).entries;
  if (entries.length > 0) {
    out.push('## Regression (your existing tests)', '', "The existing tests the plan names as the change's regression scope, as they last ran.", '', '| Test file | Result |', '|---|---|');
    for (const r of regressionResults(project, entries)) out.push(`| ${esc(r.path)} | ${r.ran ? tally(r) : 'did not run'} |`);
    out.push('');
  }
  return out;
}

/**
 * An adopted app's findings, in two lists: what fails now (new since the baseline) and the debt the
 * baseline recorded before, which is never evidence that a change works.
 */
function findingsAndDebt(project: Project, results: CheckResult[]): string[] {
  if (project.mode !== 'adopt') return [];
  const fresh = results
    .filter((r) => r.status === 'fail')
    .flatMap((r) => (r.findings.length > 0 ? r.findings.map((f) => `- ${r.id}: ${f.file ? `${f.file}${f.line ? `:${f.line}` : ''} ` : ''}${esc(f.message)}`) : [`- ${r.id}: ${esc(r.reason ?? 'fails')}`]));
  const baseline = readBaseline(project.root);
  const debt = results.filter((r) => (r.baselined ?? 0) > 0).map((r) => `| ${r.id} | ${r.baselined} | ${baseline?.checks?.[r.id] ?? baseline?.createdAt.slice(0, 10) ?? '?'} |`);
  return [
    '## New findings',
    '',
    ...(fresh.length > 0 ? fresh : ['None.']),
    '',
    '## Pre-existing debt (baseline)',
    '',
    'Findings recorded before this change. They are not evidence that it works, and a new one in the same check still fails.',
    '',
    ...(debt.length > 0 ? ['| Check | Baselined | Covered since |', '|---|---|---|', ...debt] : ['None.']),
    '',
  ];
}

export function buildReport(project: Project, results: CheckResult[], platformStatus: Record<string, string> = {}): Report {
  const changes = listChanges(project.root);
  // The change it accepts: the newest open one, else the last. An adopted app's adoption record
  // stays open by design, so it is that only until a change is delivered through fwos: closing a
  // change then leaves the report about it, and its approval valid.
  const delivered = changes.filter((c) => !isAdoptionRecord(project, c));
  const pool = delivered.length > 0 ? delivered : changes;
  const current = [...pool].reverse().find((c) => c.status === 'open') ?? pool[pool.length - 1];
  const trace = traceAcs(project);
  const signed = signoffs(changes);
  const blockers: string[] = [];
  const out: string[] = [REPORT_HEADER, '', '# Acceptance report', ''];

  // ---- acceptance criteria
  const acRows: string[] = [];
  const later: string[] = [];
  for (const t of trace?.acs ?? []) {
    const evidence =
      t.tests.length > 0
        ? t.tests
            .slice(0, 3)
            .map((c) => `\`${esc(c.name)}\` (${c.status}, ${posix.basename(c.source)})`)
            .join('<br>')
        : t.verdict === 'manual'
          ? esc(t.ac.manual ?? '')
          : 'none';
    let verdict = VERDICT_LABEL[t.verdict];
    if (t.verdict === 'manual') {
      const s = signed.get(t.ac.id);
      verdict = s ? `SIGNED OFF by ${s.by}` : 'MANUAL, waiting for sign-off';
    }
    if (t.verdict === 'failing' && t.failure) verdict += `: ${esc(t.failure)}`;
    const row = `| ${t.ac.id} | ${esc(t.ac.title)} | ${verdict} | ${t.ac.provenAgainst ?? '?'} | ${evidence} |`;
    if (t.ac.release === 'later') {
      later.push(`- ${t.ac.id}: ${t.ac.title} (${VERDICT_LABEL[t.verdict]})`);
      continue;
    }
    acRows.push(row);
    if (t.verdict === 'manual' && !signed.has(t.ac.id)) blockers.push(`${t.ac.id} is a manual check waiting for a named sign-off`);
    else if (t.verdict !== 'proven' && t.verdict !== 'manual') blockers.push(`${t.ac.id} is ${VERDICT_LABEL[t.verdict].toLowerCase()}`);
  }
  if (!trace) blockers.push('there is no spec, so there are no acceptance criteria to prove');

  // ---- gaps
  const plan = project.read(testPlanPath(project));
  const gaps = plan ? parseTestPlan(plan).gaps : [];
  for (const g of gaps) if (!signed.has(g.id)) blockers.push(`${g.id} (${g.title}) is a named gap waiting for a sign-off`);

  // ---- checks
  for (const r of results) if (r.status === 'fail') blockers.push(`check ${r.id} fails: ${r.reason ?? ''}`.trim());

  // ---- an adopted app's change: built in place, inside what it maps
  const adopted = project.mode === 'adopt' && current && !isAdoptionRecord(project, current) ? current : null;
  // A team that keeps its own practice for the implementation isn't held to the map; the trace still names the edits.
  if (adopted?.status === 'open' && adopted.map && !project.kept.includes('build')) {
    const targets = adopted.map.targets.map((t) => t.target).join(', ');
    for (const f of changeDrift(project, adopted)?.outside ?? []) blockers.push(`${f} was edited outside what the change maps (${targets})`);
  }

  const done = blockers.length === 0;
  out.push(`- Change: ${current ? `${current.id} (${current.title})` : 'none'}`);
  out.push(`- Platforms: ${project.platforms.map((p) => `${p}${platformStatus[p] ? ` (${platformStatus[p]})` : ''}`).join(', ')}`);
  out.push(`- Evidence: ${trace?.resultFiles.length ? trace.resultFiles.join(', ') : 'no test results'}`);
  out.push(`- Verdict: **${done ? 'Done' : 'Not done yet'}**`);
  out.push('');
  if (!done) {
    out.push("## What's not done", '');
    for (const b of blockers) out.push(`- ${b}`);
    out.push('');
  }

  if (adopted) out.push(...approvedInChange(project, adopted), ...importedContext(project, adopted, changes), ...traceMarkdown(project, traceChange(project, adopted)));
  else out.push(...linkedContext(project, current));
  out.push('## Acceptance criteria (first release)', '');
  if (acRows.length > 0) {
    out.push('| AC | What | Verdict | Proven against | Evidence |', '|---|---|---|---|---|', ...acRows);
  } else {
    out.push('None defined.');
  }
  out.push('');
  if (later.length > 0) out.push('Later release (not required now):', '', ...later, '');
  if (project.mode === 'adopt' && trace && trace.acs.length > 0) {
    const browser = browserResults(project);
    const seen = trace.acs.filter((t) => t.verdict === 'proven' && t.tests.some((x) => x.status === 'passed' && browser.has(x.source))).map((t) => t.ac.id);
    out.push(`Seen in a browser: ${seen.length > 0 ? seen.join(', ') : 'none yet'}.`, '');
  }
  if (project.mode === 'adopt') out.push(...runsAndRegression(project));

  out.push('## Checks', '', '| Check | Status | Why |', '|---|---|---|');
  for (const r of results) {
    const why = [r.reason, ...(r.info ?? [])].filter(Boolean).join('; ');
    out.push(`| ${r.id} | ${r.status.toUpperCase()}${r.baselined ? ` (${r.baselined} baselined)` : ''} | ${esc(why) || '-'} |`);
  }
  out.push('');
  out.push(...findingsAndDebt(project, results));

  const assumed = assumptions(project);
  out.push('## Assumptions ([ASSUMED])', '');
  out.push(...(assumed.length > 0 ? [...new Set(assumed)].map((a) => `- ${a.replace(/\n/g, ' ')}`) : ['None.']), '');

  out.push('## Skips, overrides and exceptions', '');
  const skipLines: string[] = [];
  for (const c of changes) {
    for (const s of c.skips ?? []) skipLines.push(`- ${s.target} skipped by ${s.by} in ${c.id}: ${s.reason}`);
    for (const e of c.exceptions ?? []) skipLines.push(`- ${e.target}: accepted with open finding "${e.finding}" by ${e.by} in ${c.id}`);
    for (const [target, a] of Object.entries(c.approvals)) {
      if (a.via === 'autopilot') skipLines.push(`- ${target} approved by autopilot (scripted answers) in ${c.id}; a person hasn't seen it`);
    }
  }
  out.push(...(skipLines.length > 0 ? skipLines : ['None.']), '');

  out.push('## Named gaps and manual checks', '');
  const manual = (trace?.acs ?? []).filter((t) => t.verdict === 'manual' && t.ac.release === 'first');
  if (gaps.length + manual.length === 0) out.push('None.');
  else {
    out.push('| Item | What | Sign-off |', '|---|---|---|');
    for (const g of gaps) {
      const s = signed.get(g.id);
      out.push(`| ${g.id} | ${esc(g.title)}${g.missing ? `: missing ${esc(g.missing)}` : ''} | ${s ? `${s.by}${s.note ? `: ${esc(s.note)}` : ''}` : 'waiting'} |`);
    }
    for (const m of manual) {
      const s = signed.get(m.ac.id);
      out.push(`| ${m.ac.id} | ${esc(m.ac.title)} (manual: ${esc(m.ac.manual ?? '')}) | ${s ? `${s.by}${s.note ? `: ${esc(s.note)}` : ''}` : 'waiting'} |`);
    }
  }
  out.push('');

  // Every unlock ever recorded, whether or not the test was locked again since.
  const unlocks = changes.flatMap((c) => (c.unlocks ?? []).map((u) => ({ ...u, change: c.id })));
  if (unlocks.length > 0) {
    out.push('## Unlocked tests', '');
    for (const u of unlocks) {
      out.push(`- ${u.path}: ${u.reason} (reviewer: ${u.reviewer}; ${u.relockedAt ? 'locked again' : 'still unlocked'}; ${u.change})`);
    }
    out.push('');
  }
  return { markdown: `${out.join('\n').trimEnd()}\n`, done, blockers };
}
